<?php
declare(strict_types=1);use Vendi\Database\Connection;use Vendi\Http\ApiGuard;use Vendi\Branches\BranchContextService;use Vendi\Branches\BranchClock;
require dirname(__DIR__,3).'/vendor/autoload.php';session_start();header('Content-Type: application/json; charset=utf-8');
try{$u=ApiGuard::session();if(($u['role']??'')!=='owner')throw new RuntimeException('Panel disponible para propietario.',403);$db=Connection::make(['host'=>getenv('DB_HOST')?:'127.0.0.1','port'=>(int)(getenv('DB_PORT')?:3306),'database'=>getenv('DB_DATABASE')?:'vendi','username'=>getenv('DB_USERNAME')?:'root','password'=>getenv('DB_PASSWORD')?:'']);$ctx=new BranchContextService($db);$clock=new BranchClock($db);$wanted=$_GET['branch_id']??'all';$allowed=$ctx->available($u);$rows=[];$payments=[];$hours=array_fill(0,24,0.0);$peak=null;$total=0.0;$tickets=0;$cost=0.0;foreach($allowed as$b){if($wanted!=='all'&&(int)$wanted!==(int)$b['id'])continue;$bid=(int)$b['id'];$date=$clock->now((int)$u['business_id'],$bid)->format('Y-m-d');[$from,$to]=$clock->utcRangeForLocalDate((int)$u['business_id'],$bid,$date);$q=$db->prepare("SELECT COUNT(*) tickets,COALESCE(SUM(total),0) sales,COALESCE(SUM(cost_total),0) cost,COALESCE(AVG(total),0) avg_ticket,COALESCE(MAX(total),0) peak_sale FROM sales WHERE business_id=? AND branch_id=? AND status='completed' AND completed_at_utc>=? AND completed_at_utc<?");$q->execute([(int)$u['business_id'],$bid,$from,$to]);$x=$q->fetch();$rows[]=['id'=>$bid,'name'=>$b['name'],'timezone'=>$b['timezone'],'local_date'=>$date,'tickets'=>(int)$x['tickets'],'sales'=>(float)$x['sales'],'cost'=>(float)$x['cost'],'profit'=>(float)$x['sales']-(float)$x['cost'],'avg_ticket'=>(float)$x['avg_ticket']];$total+=(float)$x['sales'];$cost+=(float)$x['cost'];$tickets+=(int)$x['tickets'];
$p=$db->prepare("SELECT COALESCE(pm.name,p.method,'Otro') method,COALESCE(SUM(p.amount-p.change_amount),0) total FROM payments p JOIN sales s ON s.id=p.sale_id LEFT JOIN payment_methods pm ON pm.id=p.payment_method_id WHERE s.business_id=? AND s.branch_id=? AND s.status='completed' AND s.completed_at_utc>=? AND s.completed_at_utc<? GROUP BY COALESCE(pm.name,p.method,'Otro')");$p->execute([(int)$u['business_id'],$bid,$from,$to]);foreach($p->fetchAll()as$r)$payments[$r['method']]=($payments[$r['method']]??0)+(float)$r['total'];
$h=$db->prepare("SELECT completed_at_utc,total FROM sales WHERE business_id=? AND branch_id=? AND status='completed' AND completed_at_utc>=? AND completed_at_utc<?");$h->execute([(int)$u['business_id'],$bid,$from,$to]);foreach($h->fetchAll()as$s){$local=$clock->displayUtc((int)$u['business_id'],$bid,$s['completed_at_utc']);$hour=(int)substr($local,11,2);$hours[$hour]+=(float)$s['total'];if(!$peak||(float)$s['total']>$peak['amount'])$peak=['amount'=>(float)$s['total'],'branch'=>$b['name'],'local_time'=>substr($local,11,5)];}}
echo json_encode(['ok'=>true,'generated_at'=>gmdate(DATE_ATOM),'branches'=>$allowed,'rows'=>$rows,'kpis'=>['sales'=>$total,'tickets'=>$tickets,'cost'=>$cost,'profit'=>$total-$cost,'avg_ticket'=>$tickets?$total/$tickets:0,'peak_sale'=>$peak],'payments'=>array_map(fn($k,$v)=>['method'=>$k,'total'=>$v],array_keys($payments),array_values($payments)),'hourly'=>array_map(fn($h,$v)=>['hour'=>sprintf('%02d:00',$h),'sales'=>$v],array_keys($hours),array_values($hours))],JSON_UNESCAPED_UNICODE);}catch(Throwable$e){http_response_code(in_array((int)$e->getCode(),[401,403],true)?(int)$e->getCode():422);echo json_encode(['ok'=>false,'error'=>$e->getMessage()],JSON_UNESCAPED_UNICODE);}